#!/usr/bin/env node

// PER-COMPONENT EXIT (b): parity >= 95%, GENERATED by this tool, not hand-counted.
//
// Parity = (vendor public members that are accounted for) / (total vendor public
// members). A member is accounted for in exactly one of the three goal buckets:
//   builder-owned        — the Syncfusion MVC builder covers it (builder.covered)
//   onboarded-typed      — a typed C# slice member exists for it (accounting.onboarded)
//   excluded-with-evidence — explicitly excluded with a written reason
//                            (a `skip:` discovery decision, or accounting.excluded[].reason)
// Anything else is UNACCOUNTED and counts against parity. Below the threshold = FAIL.
//
// Inputs (deterministic, never hand-counted):
//   <root>/<component>/discovery/public-api-surface.json  (required) — the vendor surface
//   <root>/<component>/discovery/parity-accounting.json   (optional) —
//       { "onboarded": ["vendorName", ...],
//         "excluded":  [{ "name": "vendorName", "reason": "why builder/runtime does not need it" }] }
//
// The accounting file is the per-component JUDGMENT (which candidates were onboarded
// vs excluded), reviewed like any judgment step. This tool only does the arithmetic
// and fails loud — so a 95% claim can never be a hand-wave.

import { existsSync, readFileSync } from "node:fs";
import { join, resolve } from "node:path";

const DEFAULT_ROOT = "tools/FusionOnboarding/wwwroot/onboarding/fusion";
const DEFAULT_THRESHOLD = 95;

function main() {
  const args = parseArgs(process.argv.slice(2));
  const component = requireArg(args, "component");
  const root = resolve(args.root ?? DEFAULT_ROOT);
  const threshold = Number(args.threshold ?? DEFAULT_THRESHOLD);

  const surfacePath = join(root, component, "discovery/public-api-surface.json");
  if (!existsSync(surfacePath)) {
    fail(`missing vendor surface: ${surfacePath} (run discovery first)`);
  }
  const surface = JSON.parse(readFileSync(surfacePath, "utf8"));
  const members = Array.isArray(surface.members) ? surface.members : [];
  if (members.length === 0) fail(`no members in ${surfacePath}`);

  const accounting = loadAccounting(join(root, component, "discovery/parity-accounting.json"));

  const report = classify(members, accounting);
  print(component, report, threshold);

  const parity = (report.accounted / report.total) * 100;
  process.exit(parity + 1e-9 >= threshold ? 0 : 1);
}

function classify(members, accounting) {
  const onboarded = new Set(accounting.onboarded);
  const excluded = new Map(accounting.excluded.map(item => [item.name, item.reason]));

  const buckets = { builderOwned: [], onboarded: [], excluded: [], unaccounted: [] };
  for (const member of members) {
    const name = member.name;
    if (member.builder && member.builder.covered === true) buckets.builderOwned.push(name);
    else if (onboarded.has(name)) buckets.onboarded.push(name);
    else if (/^skip/i.test(member.discoveryDecision ?? "")) buckets.excluded.push(name);
    else if (excluded.has(name)) buckets.excluded.push(name);
    else buckets.unaccounted.push(member);
  }

  const total = members.length;
  const accounted = total - buckets.unaccounted.length;
  return { total, accounted, buckets };
}

function loadAccounting(path) {
  if (!existsSync(path)) return { onboarded: [], excluded: [] };
  const raw = JSON.parse(readFileSync(path, "utf8"));
  const onboarded = Array.isArray(raw.onboarded) ? raw.onboarded.filter(n => typeof n === "string") : [];
  // An exclusion is only honored with a non-empty reason — "excluded-with-evidence".
  const excluded = Array.isArray(raw.excluded)
    ? raw.excluded.filter(item => item && typeof item.name === "string" && typeof item.reason === "string" && item.reason.trim() !== "")
    : [];
  return { onboarded, excluded };
}

function print(component, report, threshold) {
  const { total, accounted, buckets } = report;
  const parity = (accounted / total) * 100;
  const pass = parity + 1e-9 >= threshold;
  console.log(`# Fusion parity — ${component}`);
  console.log(`builder-owned        : ${buckets.builderOwned.length}`);
  console.log(`onboarded-typed      : ${buckets.onboarded.length}`);
  console.log(`excluded-with-evidence: ${buckets.excluded.length}`);
  console.log(`unaccounted          : ${buckets.unaccounted.length}`);
  console.log(`parity               : ${accounted}/${total} = ${parity.toFixed(1)}%  (threshold ${threshold}%)  -> ${pass ? "PASS" : "FAIL"}`);
  if (buckets.unaccounted.length > 0) {
    const byKind = {};
    for (const m of buckets.unaccounted) byKind[m.kind] = (byKind[m.kind] ?? 0) + 1;
    console.log("");
    console.log(`Unaccounted by kind: ${JSON.stringify(byKind)}`);
    console.log("Each unaccounted member must be onboarded-typed or excluded-with-evidence in");
    console.log("discovery/parity-accounting.json. First few:");
    for (const m of buckets.unaccounted.slice(0, 12)) console.log(`  - ${m.kind}: ${m.name}`);
    if (buckets.unaccounted.length > 12) console.log(`  ... and ${buckets.unaccounted.length - 12} more`);
  }
}

function parseArgs(items) {
  const result = {};
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (!item.startsWith("--")) continue;
    const key = item.slice(2);
    const value = items[i + 1];
    if (value === undefined || value.startsWith("--")) { result[key] = true; continue; }
    result[key] = value;
    i++;
  }
  return result;
}

function requireArg(values, name) {
  const value = values[name];
  if (typeof value === "string" && value.trim().length > 0) return value.trim();
  console.error(`Missing --${name}`);
  process.exit(2);
}

function fail(message) {
  console.error(`compute-fusion-parity: ${message}`);
  process.exit(2);
}

main();
